16	/// Why a call failed, split by whether the rest of the run can go on.
17	#[derive(Debug)]
18	pub(crate) enum CallError {
19	    /// The session is gone or stuck: every later call would fail the same way.
20	    Fatal(String),
21	    /// The checker rejected this one call; other components may still resolve.
22	    Rejected(String),
23	}
24	
25	impl std::fmt::Display for CallError {
26	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
27	        match self {
28	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
29	        }
30	    }
31	}
32	
33	fn classify(error: TscClientError) -> CallError {
34	    match error {
35	        TscClientError::RpcError { message, .. } => CallError::Rejected(message),
36	        other => CallError::Fatal(other.to_string()),
37	    }
38	}
