48	    pub name: String,
49	    pub flags: u64,
50	    #[serde(default)]
51	    pub declarations: Vec<String>,
52	    /// The symbol it is a member of: the interface or type literal that declares a property. Absent for a property a
53	    /// mapped type or an intersection made (`Omit<Base, "x">`, `A & B`), whose declarations still name the original.
54	    #[serde(default)]
55	    pub parent: Option<CompactSymbol>,
56	}
