136	impl TypeInfo {
137	    /// The checker's error type: what a name that does not resolve is typed as.
138	    pub(crate) fn is_error(&self) -> bool {
139	        self.flags & flag::ANY != 0 && self.intrinsic_name.as_deref() == Some("error")
140	    }
