279	/// A diagnostic the checker reports for a file: where it starts and what it says.
280	#[derive(Debug, Clone, Deserialize)]
281	#[serde(rename_all = "camelCase")]
282	pub(crate) struct FileDiagnostic {
283	    /// The file the error is in, which is not always the file asked about.
284	    pub file_name: String,
285	    pub start_position: Position,
286	    /// `DiagnosticCategory`: warning 0, error 1, suggestion 2, message 3.
287	    pub category: u8,
288	    /// The message; a chain of messages arrives as an object, of which only the first is shown.
289	    pub text: Value,
290	}
291	
292	impl FileDiagnostic {
293	    pub(crate) fn is_error(&self) -> bool {
294	        self.category == 1
295	    }
296	
297	    pub(crate) fn message(&self) -> String {
298	        match &self.text {
299	            Value::String(text) => text.clone(),
300	            other => other.get("messageText").and_then(Value::as_str).unwrap_or("a type error").to_string(),
301	        }
302	    }
303	}
