311	impl Rpc {
312	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
313	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
314	    /// numeric ones.
315	    pub(crate) async fn prepare(
316	        client: &Client,
317	        deadline: Duration,
318	        tsconfig: Option<&str>,
319	    ) -> Result<Value, CallError> {
320	        let rpc = Rpc {
321	            client: client.clone(),
322	            deadline,
323	            snapshot: 0,
324	            project: String::new(),
325	            options: Value::Null,
326	            recording: None,
327	            calls: Arc::default(),
328	        };
329	        rpc.call("initialize", Value::Null).await?;
330	        Ok(match tsconfig {
331	            Some(file) => {
332	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
333	                parsed.get("options").cloned().unwrap_or_else(default_options)
334	            }
335	            None => default_options(),
336	        })
337	    }
338	
339	    /// A snapshot of `count` programs over the same `root_files` (one when `count` is at most one), in a session it
340	    /// initializes first ([`Rpc::prepare`]), with one session bound to each program: a checker that answers requests
341	    /// about different programs at once ([`crate::checker::InProcess`]) answers the sessions in parallel. The programs
342	    /// read the same files, so each answers what any other would. They share the request counts and the recording;
343	    /// [`Rpc::release`] on the first releases the snapshot, and with it every program.
344	    pub(crate) async fn open_programs(
345	        client: Client,
346	        deadline: Duration,
347	        tsconfig: Option<&str>,
348	        root_files: &[String],
349	        record: bool,
350	        count: usize,
351	    ) -> Result<Vec<Rpc>, CallError> {
352	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
353	        if count <= 1 {
354	            return Ok(vec![Rpc::open_with(client, deadline, &options, root_files, record).await?]);
355	        }
356	        let first = Rpc {
357	            client,
358	            deadline,
359	            snapshot: 0,
360	            project: String::new(),
361	            options: options.clone(),
362	            recording: record.then(Arc::default),
363	            calls: Arc::default(),
364	        };
365	        let program = json!({ "rootFiles": root_files, "compilerOptions": options });
366	        let programs: Vec<Value> = std::iter::repeat_n(program, count).collect();
367	        let response: SnapshotResponse =
368	            decode(&first.call("createSnapshot", json!({ "createPrograms": programs })).await?)?;
369	        if response.projects.len() != count {
370	            return Err(CallError::Rejected(format!(
371	                "createSnapshot made {} programs of {count}",
372	                response.projects.len()
373	            )));
374	        }
375	        Ok(response
376	            .projects
377	            .into_iter()
378	            .enumerate()
379	            .map(|(lane, project)| Rpc {
380	                client: first.client.lane(lane),
381	                deadline,
382	                snapshot: response.snapshot,
383	                project: project.id,
384	                options: options.clone(),
385	                recording: first.recording.clone(),
386	                calls: first.calls.clone(),
387	            })
388	            .collect())
389	    }
390	
391	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
392	    pub(crate) async fn open_with(
393	        client: Client,
394	        deadline: Duration,
395	        options: &Value,
396	        root_files: &[String],
397	        record: bool,
398	    ) -> Result<Rpc, CallError> {
399	        let rpc = Rpc {
400	            client,
401	            deadline,
402	            snapshot: 0,
403	            project: String::new(),
404	            options: options.clone(),
405	            recording: record.then(Arc::default),
406	            calls: Arc::default(),
407	        };
408	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
409	    }
410	
411	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
412	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
413	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
414	        let rpc = Rpc {
415	            client: self.client.clone(),
416	            deadline: self.deadline,
417	            snapshot: 0,
418	            project: String::new(),
419	            options: self.options.clone(),
420	            recording: self.recording.clone(),
421	            calls: self.calls.clone(),
422	        };
423	        let mut roots = root_files.to_vec();
424	        roots.extend(files.iter().map(|(path, _)| path.clone()));
425	        let layer: serde_json::Map<String, Value> =
426	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
427	        rpc.created(json!({
428	            "fileSystem": { "kind": "layer", "files": layer },
429	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
430	        }))
431	        .await
432	    }
433	
434	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
435	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
436	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
437	    /// only when it is rebuilt. This snapshot stays alive until it is released.
438	    pub(crate) async fn updated(
439	        &self,
440	        changed: &[String],
441	        deleted: &[String],
442	        roots: Option<&[String]>,
443	    ) -> Result<Rpc, CallError> {
444	        let mut changes = serde_json::Map::new();
445	        if !changed.is_empty() || !deleted.is_empty() {
446	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
447	        }
448	        if let Some(roots) = roots {
449	            changes.insert(
450	                "reconfigurePrograms".to_string(),
451	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
452	            );
453	        }
454	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
455	        let response: SnapshotResponse =
456	            decode(&self.call("updateSnapshot", json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
457	        // The response lists only the projects it replaced; the synthetic program keeps its id.
458	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
459	        Ok(Rpc {
460	            client: self.client.clone(),
461	            deadline: self.deadline,
462	            snapshot: response.snapshot,
463	            project,
464	            options: self.options.clone(),
465	            recording: self.recording.clone(),
466	            calls: Arc::default(),
467	        })
468	    }
469	
470	    /// Every file the snapshot's program read, as the checker names them.
471	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
472	        self.scoped("getSourceFileNames", json!({})).await
473	    }
474	
475	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
476	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
477	        let response: SnapshotResponse = decode(&self.call("createSnapshot", params).await?)?;
478	        let project = response
479	            .projects
480	            .into_iter()
481	            .next()
482	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
483	        self.snapshot = response.snapshot;
484	        self.project = project.id;
485	        Ok(self)
486	    }
487	
488	    pub(crate) async fn release(&self) {
489	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
490	    }
491	
492	    /// The recorded calls as a JSON array, or `None` when recording was off.
493	    pub(crate) fn recording(&self) -> Option<Value> {
494	        let log = self.recording.as_ref()?.lock().ok()?;
495	        Some(Value::Array(log.clone()))
496	    }
497	
498	    /// Requests sent so far, by method.
499	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
500	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
501	    }
502	
503	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
504	    /// expects.
505	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
506	        if let Ok(mut calls) = self.calls.lock() {
507	            *calls.entry(method.to_string()).or_default() += 1;
508	        }
509	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
510	        let Some(log) = &self.recording else {
511	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
512	        };
513	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
514	        let result: Value = decode(&answer)?;
515	        if let Ok(mut log) = log.lock() {
516	            log.push(json!({ "method": method, "params": params, "result": result }));
517	        }
518	        Ok(answer)
519	    }
520	
521	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
522	        decode(&self.scoped_text(method, extra).await?)
523	    }
524	
525	    /// A request about this snapshot and project, its answer left as text.
526	    async fn scoped_text(&self, method: &str, extra: Value) -> Result<Box<RawValue>, CallError> {
527	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
528	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
529	            base.extend(extra);
530	        }
531	        self.call(method, params).await
532	    }
533	
534	    pub(crate) async fn source_file_symbol(&self, file: &str) -> Result<Option<SymbolInfo>, CallError> {
535	        self.scoped("getSymbolOfSourceFile", json!({ "file": file })).await
536	    }
537	
538	    pub(crate) async fn exports_of_module(&self, module: &Value) -> Result<Vec<SymbolInfo>, CallError> {
