556	    pub(crate) async fn signatures(&self, type_id: u64, kind: SignatureKind) -> Result<Vec<SignatureInfo>, CallError> {
557	        self.scoped("getSignaturesOfType", json!({ "type": type_id, "kind": kind as u8 })).await
