229	/// A warm checker that answers for the components it is asked about. Dropping it stops the checker.
230	pub struct OnDemand {
231	    jobs: Option<UnboundedSender<Job>>,
232	    thread: Option<JoinHandle<()>>,
233	    /// Receives once when the worker has stopped the checker and is about to exit.
234	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
235	    shutdown_wait: Duration,
236	    gauges: Arc<Gauges>,
237	}
238	
239	impl OnDemand {
240	    /// Starts the worker thread. The checker itself starts on the first request, or on [`OnDemand::warm_up`].
241	    pub fn new(config: OnDemandConfig) -> Self {
242	        let shutdown_wait = config.shutdown_wait;
243	        let (jobs, queue) = unbounded_channel();
244	        let (stopped_tx, stopped) = mpsc::channel();
245	        let gauges = Arc::new(Gauges::default());
246	        let worker_gauges = Arc::clone(&gauges);
247	        let thread = std::thread::Builder::new()
248	            .name("caliper-tsc".to_string())
249	            .spawn(move || {
250	                worker(config, queue, worker_gauges);
251	                stopped_tx.send(()).ok();
252	            })
253	            .ok();
254	        Self {
255	            jobs: thread.as_ref().map(|_| jobs),
256	            thread,
257	            stopped: std::sync::Mutex::new(Some(stopped)),
258	            shutdown_wait,
259	            gauges,
260	        }
261	    }
262	
263	    /// How many times the checker has been replaced so far, by cause. A replacement happens after the reply it
264	    /// follows, so read this after the next request to see the last one.
265	    pub fn recycles(&self) -> Recycles {
266	        Recycles {
267	            worn: self.gauges.worn.load(Ordering::Relaxed),
268	            bloated: self.gauges.bloated.load(Ordering::Relaxed),
269	        }
270	    }
271	
272	    /// How many snapshots the answers so far came from, by how each was made.
273	    pub fn snapshots(&self) -> Snapshots {
274	        Snapshots {
275	            created: self.gauges.created.load(Ordering::Relaxed),
276	            updated: self.gauges.updated.load(Ordering::Relaxed),
277	        }
278	    }
279	
280	    /// The operating system's id of the checker process that answered the last request, `None` before the first one and
281	    /// for the built-in checker. Read after a reply, it is the process that built that answer.
282	    pub fn process_id(&self) -> Option<u32> {
283	        Some(self.gauges.process.load(Ordering::Relaxed)).filter(|pid| *pid != 0)
284	    }
285	
286	    /// Starts the checker in the background so the first request does not pay for it.
287	    pub fn warm_up(&self) {
288	        if let Some(jobs) = &self.jobs {
289	            jobs.send(Job::Warm).ok();
290	        }
291	    }
292	}
293	
294	impl SemanticProvider for OnDemand {
295	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
296	        let (reply, receiver) = mpsc::sync_channel(1);
297	        let delivery = Delivery::new(move |outcome| {
298	            // `None` drops the sender, which the receiver reads as a checker that stopped without answering.
299	            if let Some(outcome) = outcome {
300	                reply.send(outcome).ok();
301	            }
302	        });
303	        self.request_at(targets, SharedPriority::new(Priority::Interactive), delivery);
304	        receiver
305	    }
306	
307	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
308	        match &self.jobs {
309	            Some(jobs) => {
310	                if let Err(refused) = jobs.send(Job::Answer(Asked { targets, priority, delivery }))
311	                    && let Job::Answer(asked) = refused.0
312	                {
313	                    asked.delivery.deliver(Some(SemanticOutcome::unavailable("the checker thread has stopped")));
314	                }
315	            }
316	            None => delivery.deliver(Some(SemanticOutcome::unavailable("could not start the checker thread"))),
317	        }
318	    }
319	
320	    fn changed(&self, change: SourceChange) {
321	        if let Some(jobs) = &self.jobs {
322	            jobs.send(Job::Changed(change)).ok();
323	        }
324	    }
325	}
326	
327	impl Drop for OnDemand {
328	    fn drop(&mut self) {
329	        // Closing the queue ends the worker loop, which stops the checker before the thread exits. A worker still inside
330	        // a long request is left to finish it: the checker stops when it does, or with this process.
331	        self.jobs.take();
332	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
333	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
334	        if let Some(thread) = self.thread.take()
335	            && stopped
336	        {
337	            thread.join().ok();
338	        }
339	    }
340	}
341	
342	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
343	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
344	        Ok(runtime) => runtime,
345	        Err(error) => {
346	            let reason = format!("could not start an async runtime: {error}");
347	            while let Some(job) = queue.blocking_recv() {
348	                match job {
349	                    Job::Answer(asked) => asked.delivery.deliver(Some(SemanticOutcome::unavailable(reason.clone()))),
350	                    Job::Warm | Job::Changed(_) => {}
351	                }
352	            }
353	            return;
354	        }
355	    };
356	    runtime.block_on(async move {
357	        let mut checker = Checker { gauges, ..Checker::default() };
358	        let mut waiting = Queue::default();
359	        let mut open = true;
360	        loop {
361	            // Every job sent so far is taken before the next request is picked, so the queues hold every request that
362	            // waits, and a change is applied before any request sent after it.
363	            if waiting.is_empty() && open {
364	                match queue.recv().await {
365	                    Some(job) => checker.take(&config, job, &mut waiting).await,
366	                    None => open = false,
367	                }
368	            }
369	            while open {
370	                match queue.try_recv() {
371	                    Ok(job) => checker.take(&config, job, &mut waiting).await,
372	                    Err(TryRecvError::Empty) => break,
373	                    Err(TryRecvError::Disconnected) => open = false,
374	                }
375	            }
376	            let Some(asked) = waiting.next() else {
377	                match open {
378	                    true => continue,
379	                    false => break,
380	                }
381	            };
382	            asked.delivery.deliver(Some(checker.answer(&config, asked.targets).await));
383	            // After the reply, so the caller never waits for the memory check or the replacement.
384	            checker.maintain(&config).await;
385	        }
386	        if let Some(backend) = checker.backend.take() {
387	            backend.shutdown().await;
388	        }
389	    });
390	}
391	
392	#[derive(Default)]
393	struct Checker {
394	    backend: Option<Backend>,
395	    /// Compiler options read once from the tsconfig for the running checker.
396	    options: Option<serde_json::Value>,
397	    restarts: u32,
398	    /// Requests the running checker has answered.
399	    served: u32,
400	    /// Why the checker cannot be used for the rest of the session.
401	    down: Option<String>,
402	    gauges: Arc<Gauges>,
403	    /// The snapshot the last request was answered from, kept for the next.
404	    live: Option<Live>,
405	    /// Files announced as changed since `live` was brought up to date.
406	    told: FxHashSet<Utf8PathBuf>,
407	}
408	
409	/// A snapshot kept between requests, and what its program read.
410	struct Live {
411	    rpc: Arc<Rpc>,
412	    /// The files its program is rooted at.
413	    roots: Vec<String>,
414	    /// When the files were compared with the disk, just before the snapshot was built or brought up to date.
415	    read_from: SystemTime,
416	    /// Every file the program read, as it was then; `None` until listed after the reply the snapshot built.
417	    stamps: Option<FxHashMap<Utf8PathBuf, Stamp>>,
418	}
419	
420	/// The warning an answer carries when files the snapshot read changed and the checker was not told.
421	fn untold_warning(files: &[Utf8PathBuf]) -> Diagnostic {
422	    let mut named: Vec<String> = files.iter().take(UNTOLD_NAMED).map(ToString::to_string).collect();
423	    if files.len() > UNTOLD_NAMED {
424	        named.push(format!("{} more", files.len() - UNTOLD_NAMED));
425	    }
426	    Diagnostic::new(
427	        DiagnosticSeverity::Warning,
428	        DiagnosticCode::SemanticBackend,
429	        format!(
430	            "the TypeScript checker was not told that {} changed; it read every file again for this answer",
431	            named.join(", ")
432	        ),
433	    )
434	    .with_help(
435	        "Whatever writes the project's files must tell the session (`update_file` or `ensure_fresh`); an edit the \
436	         checker is not told about is answered from the text it read before.",
437	    )
438	}
439	
440	impl Checker {
441	    /// Acts on a job as it arrives: starts the process, applies a change, or files a request by its priority.
442	    async fn take(&mut self, config: &OnDemandConfig, job: Job, waiting: &mut Queue<Asked>) {
443	        match job {
444	            Job::Warm => {
445	                self.ensure(config).await.ok();
446	            }
447	            Job::Changed(change) => self.told(change).await,
448	            Job::Answer(asked) => {
449	                let priority = asked.priority.clone();
450	                waiting.push(asked, priority);
451	            }
452	        }
453	    }
454	
455	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
456	        if let Some(reason) = &self.down {
457	            return Err(reason.clone());
458	        }
459	        if self.backend.as_ref().is_some_and(|backend| !backend.is_alive()) {
460	            if let Some(dead) = self.backend.take() {
461	                dead.shutdown().await;
462	            }
463	            self.options = None;
464	            self.live = None;
465	            self.told.clear();
466	            self.restarts += 1;
467	            if self.restarts > MAX_RESTARTS {
468	                return Err(self.stay_down("the checker kept crashing".to_string()));
469	            }
470	        }
471	        if self.backend.is_none() {
472	            let request = SemanticRequest {
473	                project_root: config.project_root.clone(),
474	                tsconfig: config.tsconfig.clone(),
475	                tsc_path: config.tsc_path.clone(),
476	                targets: Vec::new(),
477	                request_timeout: config.request_timeout,
478	                expected_versions: config.expected_versions,
479	                record_to: None,
480	                extra_env: config.extra_env.clone(),
481	                reverse_queries: false,
482	            };
483	            let backend = start_checker(&request, 1).await.map_err(|reason| self.stay_down(reason))?;
484	            // Initialize the session and read the compiler options once; every request after builds only its program.
485	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
486	            match Rpc::prepare(&backend.client(), config.request_timeout, tsconfig).await {
487	                Ok(options) => self.options = Some(options),
488	                Err(error) => {
489	                    backend.shutdown().await;
490	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
491	                }
492	            }
493	            self.backend = Some(backend);
494	        }
495	        Ok(())
496	    }
497	
498	    fn stay_down(&mut self, reason: String) -> String {
499	        self.down = Some(reason.clone());
500	        reason
501	    }
502	
503	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
504	        if let Err(reason) = self.ensure(config).await {
505	            return SemanticOutcome::unavailable(reason);
506	        }
507	        let Some(backend) = self.backend.as_ref() else {
508	            return SemanticOutcome::unavailable("the checker is not running");
509	        };
510	        let (client, process) = (backend.client(), backend.process_id());
511	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
512	        request.tsconfig = config.tsconfig.clone();
513	        request.tsc_path = config.tsc_path.clone();
514	        request.request_timeout = config.request_timeout;
515	        request.expected_versions = config.expected_versions;
516	        request.extra_env.clone_from(&config.extra_env);
517	        let roots = root_files(&request);
518	        if roots.is_empty() {
519	            return group_by_file(&request).0;
520	        }
521	        let answered = match self.snapshot_for(client, config.request_timeout, roots.clone()).await {
522	            Ok((rpc, warning)) => answer_on(std::slice::from_ref(&rpc), &request, &roots).await.map(|mut outcome| {
523	                outcome.diagnostics.extend(warning);
524	                outcome
525	            }),
526	            Err(error) => Err(error),
527	        };
528	        self.gauges.process.store(process.unwrap_or(0), Ordering::Relaxed);
529	        self.served += 1;
530	        match answered {
531	            Ok(outcome) => outcome,
532	            Err(error) => {
533	                self.forget().await;
534	                SemanticOutcome::unavailable(format!("the checker stopped answering: {error}"))
535	            }
536	        }
537	    }
538	
539	    /// The snapshot to answer from, its program rooted at `roots`: the kept one brought up to date with the files the
540	    /// checker was told about, or a fresh one when none is kept, the kept one cannot be checked or updated, or a file
541	    /// it read changed with nobody telling the checker. The last comes with a warning that names the files.
542	    async fn snapshot_for(
543	        &mut self,
544	        client: Client,
545	        deadline: Duration,
546	        roots: Vec<String>,
547	    ) -> Result<(Arc<Rpc>, Option<Diagnostic>), CallError> {
548	        let read_from = SystemTime::now();
549	        let told = std::mem::take(&mut self.told);
550	        let mut warning = None;
551	        if let Some(live) = self.live.take() {
552	            if let Some(stamps) = &live.stamps {
553	                let drift = stamps::drift(stamps, &told);
554	                if drift.untold.is_empty() {
555	                    let reread: BTreeSet<Utf8PathBuf> = told.into_iter().chain(drift.unsure).collect();
556	                    if reread.is_empty() && live.roots == roots {
557	                        let rpc = live.rpc.clone();
558	                        self.live = Some(live);
559	                        return Ok((rpc, None));
560	                    }
561	                    let (changed, deleted): (Vec<String>, Vec<String>) = {
562	                        let (present, gone): (Vec<_>, Vec<_>) = reread.into_iter().partition(|file| file.exists());
563	                        (present.into_iter().map(String::from).collect(), gone.into_iter().map(String::from).collect())
564	                    };
565	                    let rerooted = (live.roots != roots).then_some(roots.as_slice());
566	                    match live.rpc.updated(&changed, &deleted, rerooted).await {
567	                        Ok(rpc) => {
568	                            live.rpc.release().await;
569	                            let rpc = Arc::new(rpc);
570	                            self.gauges.updated.fetch_add(1, Ordering::Relaxed);
571	                            self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
572	                            return Ok((rpc, None));
573	                        }
574	                        Err(CallError::Rejected(message)) => {
575	                            tracing::debug!(%message, "the checker could not update its snapshot; building a fresh one");
576	                        }
577	                        Err(fatal) => return Err(fatal),
578	                    }
579	                } else {
580	                    tracing::warn!(files = ?drift.untold, "files changed that the checker was not told about");
581	                    warning = Some(untold_warning(&drift.untold));
582	                }
583	            }
584	            live.rpc.release().await;
585	        }
586	        let options = self.options.as_ref().ok_or_else(|| CallError::Fatal("the checker is not initialized".into()))?;
587	        let rpc = Arc::new(Rpc::open_with(client, deadline, options, &roots, false).await?);
588	        self.gauges.created.fetch_add(1, Ordering::Relaxed);
589	        self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
590	        Ok((rpc, warning))
591	    }
592	
593	    /// Files changed on disk: the kept snapshot reads them again at the next request, or, when anything may have
594	    /// changed, is dropped.
595	    async fn told(&mut self, change: SourceChange) {
596	        match change {
597	            SourceChange::Files(files) if self.live.is_some() => self.told.extend(files),
598	            SourceChange::Files(_) => {}
599	            SourceChange::Everything => self.forget().await,
600	        }
601	    }
602	
603	    /// Drops the kept snapshot, so the next request builds one from the disk.
604	    async fn forget(&mut self) {
605	        self.told.clear();
606	        if let Some(live) = self.live.take() {
607	            live.rpc.release().await;
608	        }
609	    }
610	
611	    /// Lists and stamps the files the kept snapshot's program read, once, after the reply it answered, so the first
612	    /// answer does not wait for it. A snapshot that cannot be listed cannot be checked, and is dropped.
613	    async fn stamp(&mut self) {
614	        let Some(live) = self.live.as_mut().filter(|live| live.stamps.is_none()) else { return };
615	        match live.rpc.source_file_names().await {
616	            Ok(files) => {
617	                live.stamps = Some(stamps::record(files.into_iter().map(Utf8PathBuf::from).collect(), live.read_from))
618	            }
619	            Err(error) => {
620	                tracing::debug!(%error, "could not list the snapshot's files; the next request builds a fresh one");
621	                self.forget().await;
622	            }
623	        }
624	    }
625	
626	    /// Replaces the checker when it has built enough programs or (a process) grown past the memory bound, and otherwise
627	    /// stamps the snapshot it keeps. A planned replacement, not a crash: the next request starts a fresh checker.
628	    async fn maintain(&mut self, config: &OnDemandConfig) {
629	        let Some(backend) = self.backend.as_ref() else { return };
630	        let worn = self.served >= MAX_REQUESTS_PER_PROCESS;
631	        let resident = (!worn && self.served.is_multiple_of(RSS_CHECK_EVERY))
632	            .then(|| backend.process_id().and_then(resident_mib))
633	            .flatten();
634	        let bloated = resident.is_some_and(|mib| mib > config.max_rss_mib);
635	        if worn || bloated {
636	            let (count, cause) = if worn { (&self.gauges.worn, "worn") } else { (&self.gauges.bloated, "bloated") };
637	            count.fetch_add(1, Ordering::Relaxed);
638	            tracing::debug!(cause, served = self.served, resident_mib = ?resident, "replacing the checker");
639	            // The snapshot goes with the checker; the next one reads every file from the disk.
640	            self.live = None;
641	            self.told.clear();
642	            if let Some(old) = self.backend.take() {
643	                old.shutdown().await;
644	            }
645	            self.options = None;
646	            self.served = 0;
647	            return;
648	        }
649	        self.stamp().await;
650	    }
651	}
652	
653	#[cfg(test)]
654	mod tests {
655	    use caliper_docgen_core::types::semantic::{Priority, SharedPriority};
656	
657	    use super::{INTERACTIVE_STREAK, Queue, resident_mib};
658	
659	    fn drain(queue: &mut Queue<&'static str>) -> Vec<&'static str> {
660	        std::iter::from_fn(|| queue.next()).collect()
661	    }
662	
663	    fn push(queue: &mut Queue<&'static str>, item: &'static str, priority: Priority) -> SharedPriority {
664	        let priority = SharedPriority::new(priority);
665	        queue.push(item, priority.clone());
666	        priority
667	    }
668	
669	    #[test]
670	    fn an_interactive_request_goes_before_every_background_one_and_each_queue_keeps_its_order() {
671	        let mut queue = Queue::default();
672	        push(&mut queue, "fill 1", Priority::Background);
673	        push(&mut queue, "fill 2", Priority::Background);
674	        push(&mut queue, "story 1", Priority::Interactive);
675	        push(&mut queue, "fill 3", Priority::Background);
676	        push(&mut queue, "story 2", Priority::Interactive);
677	
678	        assert_eq!(drain(&mut queue), ["story 1", "story 2", "fill 1", "fill 2", "fill 3"]);
679	    }
680	
681	    #[test]
682	    fn a_background_request_raised_while_it_waits_goes_with_the_interactive_ones() {
683	        let mut queue = Queue::default();
684	        push(&mut queue, "fill 1", Priority::Background);
685	        let prefetch = push(&mut queue, "prefetch of the story", Priority::Background);
686	        push(&mut queue, "story", Priority::Interactive);
687	
688	        prefetch.raise();
689	
690	        assert_eq!(drain(&mut queue), ["story", "prefetch of the story", "fill 1"]);
691	    }
692	
693	    #[test]
694	    fn a_waiting_background_request_goes_after_a_bounded_run_of_interactive_ones() {
695	        assert_eq!(INTERACTIVE_STREAK, 4);
696	        let mut queue = Queue::default();
697	        push(&mut queue, "fill 1", Priority::Background);
698	        push(&mut queue, "fill 2", Priority::Background);
699	        for story in ["story 1", "story 2", "story 3", "story 4", "story 5", "story 6", "story 7", "story 8", "story 9"]
700	        {
701	            push(&mut queue, story, Priority::Interactive);
702	        }
703	
704	        assert_eq!(
705	            drain(&mut queue),
706	            [
707	                "story 1", "story 2", "story 3", "story 4", "fill 1", "story 5", "story 6", "story 7", "story 8",
708	                "fill 2", "story 9"
709	            ]
710	        );
711	    }
712	
713	    #[test]
714	    fn interactive_requests_with_no_background_waiting_do_not_count_toward_the_bound() {
715	        let mut queue = Queue::default();
716	        for story in ["story 1", "story 2", "story 3", "story 4", "story 5"] {
717	            push(&mut queue, story, Priority::Interactive);
718	            assert_eq!(queue.next(), Some(story));
719	        }
720	        push(&mut queue, "fill", Priority::Background);
721	        push(&mut queue, "story 6", Priority::Interactive);
722	
723	        assert_eq!(drain(&mut queue), ["story 6", "fill"]);
724	    }
