+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+enum Upkeep {
+    /// It keeps answering.
+    Keep,
+    /// A process replaced after [`MAX_REQUESTS_PER_PROCESS`] programs.
+    Worn,
+    /// A process replaced because it holds more than the memory bound.
+    Bloated,
