+            (false, _) if served >= MAX_REQUESTS_PER_PROCESS => Upkeep::Worn,
+            (false, true) => Upkeep::Bloated,
+            (true, true) => Upkeep::Down,
+            (_, false) => Upkeep::Keep,
+        }
+    }
+}
