1	#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
2	//! The warm checker against `replay-tsc` (the recording of the real `7.1.0-beta`): one process answers requests for
3	//! one component at a time, and a checker that cannot start says so and never fails a request.
4	
5	use std::time::Duration;
6	
7	use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, WatchSession, extract};
8	use caliper_docgen_core::types::semantic::{
9	    Delivery, Priority, SemanticOutcome, SemanticProvider, SemanticTarget, SharedPriority,
10	};
11	use caliper_docgen_core::types::{DiagnosticSeverity, ExtractionOutput, PropType};
12	use caliper_docgen_semantic::{OnDemand, OnDemandConfig, Recycles, targets_of};
13	use camino::Utf8PathBuf;
14	
15	const FAKE_VERSION: &str = "7.1.0-test";
16	
17	struct Project {
18	    _dir: tempfile::TempDir,
19	    root: Utf8PathBuf,
20	}
21	
22	/// The fixture project in a scratch directory whose name has an upper-case letter (see `replay_tsc.rs`), with
23	/// `replay-tsc` installed as `node_modules/typescript/bin/tsc` when `with_tsc`.
24	fn project(with_tsc: bool) -> Project {
25	    let dir = tempfile::Builder::new().prefix("Replay").tempdir().unwrap();
26	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
27	    let fixtures = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures");
28	    for name in ["Button.tsx", "tsconfig.json"] {
29	        std::fs::copy(fixtures.join("project").join(name), root.join(name)).unwrap();
30	    }
31	    if with_tsc {
32	        let package = root.join("node_modules/typescript");
33	        std::fs::create_dir_all(package.join("bin")).unwrap();
34	        std::fs::write(package.join("package.json"), format!(r#"{{"version": "{FAKE_VERSION}"}}"#)).unwrap();
35	        std::fs::copy(env!("CARGO_BIN_EXE_replay-tsc"), package.join("bin/tsc")).unwrap();
36	    }
37	    Project { _dir: dir, root }
38	}
39	
40	fn structural(project: &Project) -> ExtractionOutput {
41	    extract(&PipelineOptions { src_dirs: vec![project.root.clone()], ..PipelineOptions::default() })
42	}
43	
44	fn checker(project: &Project) -> OnDemand {
45	    let mut config = OnDemandConfig::new(project.root.clone());
46	    config.tsc_path = Some(project.root.join("node_modules/typescript/bin/tsc"));
47	    config.expected_versions = &[FAKE_VERSION];
48	    config.request_timeout = Duration::from_secs(20);
49	    config
50	        .extra_env
51	        .push(("REPLAY_FIXTURE".to_string(), format!("{}/tests/fixtures/recording.json", env!("CARGO_MANIFEST_DIR"))));
52	    OnDemand::new(config)
53	}
54	
55	fn target(output: &ExtractionOutput, name: &str) -> SemanticTarget {
56	    targets_of(output).into_iter().find(|target| target.display_name == name).unwrap()
57	}
58	
59	fn ask(checker: &OnDemand, target: SemanticTarget) -> SemanticOutcome {
60	    checker.request(vec![target]).recv_timeout(Duration::from_secs(30)).expect("the checker answers")
61	}
62	
63	fn ask_in_background(checker: &OnDemand, target: SemanticTarget) -> SemanticOutcome {
64	    let (sender, receiver) = std::sync::mpsc::channel();
65	    let delivery = Delivery::new(move |outcome| {
66	        sender.send(outcome).ok();
67	    });
68	    checker.request_at(vec![target], SharedPriority::new(Priority::Background), delivery);
69	    receiver.recv_timeout(Duration::from_secs(30)).expect("a delivery").expect("the checker answers")
70	}
