72	/// A story asked while background requests wait is answered before them. `REPLAY_HOLD` keeps the checker starting
73	/// until every request is queued; the answers arrive in the order the one worker gives them.
74	#[test]
75	fn a_story_asked_behind_queued_background_requests_is_answered_before_them() {
76	    let project = project(true);
77	    let output = structural(&project);
78	    let hold = project.root.join("hold");
79	    let mut config = OnDemandConfig::new(project.root.clone());
80	    config.tsc_path = Some(project.root.join("node_modules/typescript/bin/tsc"));
81	    config.expected_versions = &[FAKE_VERSION];
82	    config.request_timeout = Duration::from_secs(20);
83	    config
84	        .extra_env
85	        .push(("REPLAY_FIXTURE".to_string(), format!("{}/tests/fixtures/recording.json", env!("CARGO_MANIFEST_DIR"))));
86	    config.extra_env.push(("REPLAY_HOLD".to_string(), hold.to_string()));
87	    let checker = OnDemand::new(config);
88	    checker.warm_up();
89	    let (sender, answered) = std::sync::mpsc::channel();
90	    let queue = |name: &'static str, priority: Priority| {
91	        let sender = sender.clone();
92	        let delivery = Delivery::new(move |outcome| {
93	            sender.send((name, outcome)).ok();
94	        });
95	        checker.request_at(vec![target(&output, name)], SharedPriority::new(priority), delivery);
96	    };
97	    for _ in 0..3 {
98	        queue("Button", Priority::Background);
99	    }
100	    queue("Other", Priority::Interactive);
101	
102	    std::fs::write(&hold, "").unwrap();
103	    let order: Vec<&str> = (0..4)
104	        .map(|_| {
105	            let (name, outcome) = answered.recv_timeout(Duration::from_secs(30)).expect("an answer");
106	            let outcome = outcome.expect("the checker answered");
107	            assert_eq!(outcome.components.len(), 1, "{name}: {:?}", outcome.diagnostics);
108	            name
109	        })
110	        .collect();
111	
112	    assert_eq!(order, ["Other", "Button", "Button", "Button"]);
113	}
