312	        root.join("tsconfig.json"),
313	    )
314	    .unwrap();
315	    let sources = [
316	        (
317	            "WithChildren.tsx",
318	            "import type { PropsWithChildren } from \"react\";\nexport function WithChildren(props: PropsWithChildren<{ label: string }>) { return null; }\n",
319	        ),
