342	            .with_semantic(std::sync::Arc::new(OnDemand::new(config)), Duration::from_secs(60));
343	        drop(checked.initialize());
344	
345	        for key in ["WithChildren", "OwnChildren", "Div"] {
346	            let before = structural.component(key).unwrap();
347	            let after = checked.component(key).unwrap();
348	            assert!(
349	                after.diagnostics.iter().any(|d| d.message.contains("resolved by the TypeScript checker")),
350	                "{key} under {mode:?} was not answered by the checker: {:?}",
351	                after.diagnostics
352	            );
353	            let names = |answer: &caliper_docgen_core::pipeline::ComponentAnswer| -> Vec<String> {
354	                answer.entry.props.keys().cloned().collect()
355	            };
