2	//! A warm checker kept across edits (ADR 0026 S6), against a real checker: a `tsrs` process when `TSRS_BIN` names its
3	//! binary, else the Go `typescript@7.1` when `CALIPER_TEST_TSC` names its `bin/tsc`, else the built-in checker.
4	//!
5	//! An edit the session announces is read from the kept snapshot brought up to date; one nobody announces is found
6	//! before the checker answers from the old text, and the answer comes from the disk with a warning naming the file.
7	
8	use std::sync::Arc;
9	use std::time::{Duration, SystemTime};
10	
11	use caliper_docgen_core::pipeline::{ComponentAnswer, PipelineOptions, WatchSession};
12	use caliper_docgen_core::types::semantic::{SemanticOutcome, SemanticProvider, SemanticTarget, SourceChange};
13	use caliper_docgen_core::types::{DiagnosticSeverity, ExtractionOutput};
14	use caliper_docgen_semantic::{OnDemand, OnDemandConfig, Snapshots, targets_of};
15	use camino::{Utf8Path, Utf8PathBuf};
16	
17	/// The checker binary to run as a process; `None` asks the built-in checker.
18	fn real_checker() -> Option<Utf8PathBuf> {
19	    ["TSRS_BIN", "CALIPER_TEST_TSC"]
20	        .into_iter()
21	        .find_map(|name| std::env::var(name).ok().filter(|value| !value.is_empty()))
22	        .map(Utf8PathBuf::from)
23	}
24	
25	const BUTTON: &str = "import type { Shared } from \"./shared\";\nexport function Button(props: Shared & { label: string }) { return null; }\n";
26	const CARD: &str = "export function Card(props: { title: string }) { return null; }\n";
27	
28	fn shared(version: usize) -> String {
29	    format!("export interface Shared {{ shared{version}: string }}\n")
30	}
31	
32	struct Project {
33	    _dir: tempfile::TempDir,
34	    root: Utf8PathBuf,
35	}
36	
37	impl Project {
38	    /// `Button.tsx`, which takes its props from `shared.ts`, and `Card.tsx`, all written an hour ago: a stamp taken
39	    /// within two seconds of an edit cannot tell it from the next, and a checker reads such a file again unasked.
40	    fn new() -> Self {
41	        let dir = tempfile::Builder::new().prefix("Watch").tempdir().unwrap();
42	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
43	        let fixture = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/project/tsconfig.json");
44	        std::fs::copy(fixture, root.join("tsconfig.json")).unwrap();
45	        let project = Self { _dir: dir, root };
46	        for (name, text) in
47	            [("Button.tsx", BUTTON.to_string()), ("Card.tsx", CARD.to_string()), ("shared.ts", shared(0))]
48	        {
49	            project.write_settled(name, &text);
50	        }
51	        project
52	    }
53	
54	    fn file(&self, name: &str) -> Utf8PathBuf {
55	        self.root.join(name)
56	    }
57	
58	    fn write_settled(&self, name: &str, text: &str) {
59	        std::fs::write(self.file(name), text).unwrap();
60	        let file = std::fs::File::options().write(true).open(self.file(name)).unwrap();
61	        file.set_modified(SystemTime::now() - Duration::from_secs(3600)).unwrap();
62	    }
63	
64	    fn checker(&self, tsc: Option<&Utf8Path>) -> Arc<OnDemand> {
65	        let mut config = OnDemandConfig::new(self.root.clone());
66	        config.tsconfig = Some(self.file("tsconfig.json"));
67	        config.tsc_path = tsc.map(Utf8Path::to_owned);
68	        config.request_timeout = Duration::from_secs(60);
69	        Arc::new(OnDemand::new(config))
70	    }
