7	//! JSON line: `structuralMs`, then for `project` the single `projectMs`, or for `on-demand` `startMs` (spawn and
8	//! handshake), `firstMs` (the first component, with a cold program) and `eachMs` (the rest, sorted), plus how many
9	//! components the checker answered and the props it found against the structural pass.
10	use std::time::{Duration, Instant};
11	
12	use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, extract};
13	use caliper_docgen_core::types::semantic::SemanticProvider;
14	use caliper_docgen_semantic::{OnDemand, OnDemandConfig, SemanticRequest, resolve, targets_of};
15	use camino::Utf8PathBuf;
16	
17	fn arg(args: &[String], name: &str) -> Option<String> {
18	    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
19	}
20	
21	fn ms(duration: Duration) -> f64 {
22	    duration.as_secs_f64() * 1000.0
23	}
24	
25	fn percentile(sorted: &[f64], p: f64) -> f64 {
26	    if sorted.is_empty() {
27	        return 0.0;
28	    }
29	    sorted[((sorted.len() - 1) as f64 * p).round() as usize]
30	}
31	
32	fn main() {
33	    let args: Vec<String> = std::env::args().collect();
34	    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
35	    let tsc = Utf8PathBuf::from(arg(&args, "--tsc").expect("--tsc"));
36	    let tsconfig = arg(&args, "--tsconfig").map(Utf8PathBuf::from);
37	    let mode = arg(&args, "--mode").unwrap_or_else(|| "on-demand".to_string());
38	    let count: usize = arg(&args, "--count").map_or(50, |n| n.parse().expect("--count"));
39	    let batch: usize = arg(&args, "--batch").map_or(1, |n| n.parse().expect("--batch"));
40	    let mut seed: u64 = arg(&args, "--seed").map_or(1, |n| n.parse().expect("--seed")) | 1;
41	
42	    let options = PipelineOptions {
43	        src_dirs: vec![src.clone()],
44	        load_dependencies: true,
45	        html_attributes: HtmlAttributeMode::Curated,
46	        ..Default::default()
47	    };
48	    let started = Instant::now();
49	    let output = extract(&options);
50	    let structural_ms = ms(started.elapsed());
51	    let all = targets_of(&output);
52	    let structural_props: usize = output.components.values().map(|entry| entry.props.len()).sum();
53	    let root = std::fs::canonicalize(&src).ok().and_then(|p| Utf8PathBuf::from_path_buf(p).ok()).unwrap_or(src);
54	
55	    if mode == "project" {
56	        let mut request = SemanticRequest::new(root, all.clone());
57	        request.tsconfig = tsconfig;
58	        request.tsc_path = Some(tsc);
59	        let started = Instant::now();
60	        let outcome = resolve(request);
61	        println!(
62	            "{{\"mode\":\"project\",\"components\":{},\"structuralMs\":{structural_ms:.1},\"projectMs\":{:.1},\"answered\":{},\"props\":{}}}",
63	            all.len(),
64	            ms(started.elapsed()),
65	            outcome.components.len(),
66	            outcome.components.iter().map(|c| c.props.len()).sum::<usize>(),
67	        );
68	        return;
69	    }
70	
71	    let mut config = OnDemandConfig::new(root);
72	    config.tsconfig = tsconfig;
73	    config.tsc_path = Some(tsc);
74	    let started = Instant::now();
75	    let checker = OnDemand::new(config);
76	    checker.warm_up();
77	    // A request queued behind the warm-up returns when the process is up and the first program is built.
78	    let mut picks: Vec<_> = Vec::new();
79	    let exported: Vec<_> = all.iter().filter(|t| !t.exports.is_empty()).cloned().collect();
80	    for _ in 0..count.min(exported.len()) {
81	        seed ^= seed << 13;
82	        seed ^= seed >> 7;
83	        seed ^= seed << 17;
84	        picks.push(exported[(seed as usize) % exported.len()].clone());
85	    }
86	    let mut times = Vec::new();
87	    let mut answered = 0usize;
88	    let mut found_props = 0usize;
89	    let mut structural_of_answered = 0usize;
90	    let mut fallbacks = 0usize;
91	    let mut unavailable = String::new();
